<?php
declare(strict_types=1);
function app_device_id(): string {if(!empty($_SESSION['trusted_id']))return (string)$_SESSION['trusted_id'];return hash_hmac('sha256',session_id(),(string)app_config('app_key'));}
function app_device_check(array $user): bool {
    if(PHP_SAPI==='cli'||session_id()==='')return true;$id=app_device_id();$d=comm_get('session.'.$id);if(function_exists('app_trust_renew'))app_trust_renew();if(!empty($d['revoked']))return false;
    $prefs=comm_get('preferences.'.$user['id']);$idle=(int)($prefs['idle_minutes']??0);if($idle>0&&isset($_SESSION['interactive_at'])&&$_SESSION['interactive_at']<time()-$idle*60){if(function_exists('app_trust_forget'))app_trust_forget();return false;}$_SESSION['interactive_at']??=time();
    if(!$d||($d['seen']??0)<time()-600){comm_put('session.'.$id,['id'=>$id,'user'=>(int)$user['id'],'label'=>mb_substr((string)($_SERVER['HTTP_USER_AGENT']??'Browser'),0,180),'created'=>$d['created']??time(),'seen'=>time(),'revoked'=>false]);}
    return true;
}
function app_passkeys(int $uid): array {return array_values(array_filter(comm_records('passkey',200),static fn($r)=>(int)$r['user']===$uid));}
function app_binary(mixed $v,int $max=100000): string {if(!is_string($v)||strlen($v)>$max||!preg_match('/^[A-Za-z0-9+\/_=-]+$/D',$v))throw new InvalidArgumentException('Invalid credential response.');$r=base64_decode(strtr($v,'-_','+/'),true);if($r===false||$r==='')throw new InvalidArgumentException('Invalid credential response.');return $r;}
function app_credential_origin(string $client,string $type): void {$d=json_decode($client,true,8,JSON_THROW_ON_ERROR);if(($d['origin']??'')!==rtrim(base_url(),'/')||!empty($d['crossOrigin'])||($d['type']??'')!==$type)throw new InvalidArgumentException('The credential belongs to another origin or action.');}
function app_webauthn(): \lbuchs\WebAuthn\WebAuthn {return new \lbuchs\WebAuthn\WebAuthn('Waithaka Ndegwa',(string)parse_url(base_url(),PHP_URL_HOST),['none'],true);}
function app_challenge(string $purpose): string {$r=$_SESSION['passkey_challenge']??[];unset($_SESSION['passkey_challenge']);if(($r['purpose']??'')!==$purpose||($r['expires']??0)<time())throw new InvalidArgumentException('This credential request expired. Start again.');return base64_decode($r['value'],true);}
function app_password_check(int $uid,mixed $password): void {$q=db()->prepare('SELECT email,password_hash FROM users WHERE id=? AND is_active=1');$q->execute([$uid]);$u=$q->fetch();if(!$u||!is_string($password)||login_rate_limited($u['email']))throw new InvalidArgumentException('Verify your current password.');$ok=password_verify($password,$u['password_hash']);db()->prepare('INSERT INTO login_attempts(email,ip_hash,success) VALUES(?,?,?)')->execute([$u['email'],ip_hash(),$ok?1:0]);if(!$ok)throw new InvalidArgumentException('Your current password was not accepted.');}
function app_security_dispatch(string $path): bool {
    if(!in_array($path,['/write/security','/write/passkey','/write/security/lock','/write/security/activity'],true))return false;private_response_headers();journeys_method(['GET','HEAD','POST']);$error='';
    if($path==='/write/passkey'){
        journeys_method(['POST']);verify_csrf();try{
            if(!journeys_rate_limit('passkey',ip_hash(),20,300))throw new RuntimeException('Please wait before trying again.');$action=$_POST['action']??'';$w=app_webauthn();
            if($action==='register_options'){require_auth();$u=current_user();app_password_check((int)$u['id'],$_POST['password']??'');if(count(app_passkeys((int)$u['id']))>=10)throw new RuntimeException('Remove an older passkey first.');$ids=array_map(static fn($r)=>base64_decode($r['credential']),app_passkeys((int)$u['id']));$handle=hash_hmac('sha256','passkey-user|'.$u['id'],(string)app_config('app_key'),true);$args=$w->getCreateArgs($handle,$u['email'],$u['name'],120,true,true,null,$ids);$_SESSION['passkey_challenge']=['value'=>base64_encode($w->getChallenge()->getBinaryString()),'purpose'=>'register','expires'=>time()+180,'user'=>(int)$u['id']];comm_json(['ok'=>true,'options'=>$args]);}
            if($action==='register_finish'){require_auth();$u=current_user();$expected=$_SESSION['passkey_challenge']['user']??0;if($expected!==(int)$u['id'])throw new InvalidArgumentException('Credential user changed.');$challenge=app_challenge('register');$client=app_binary($_POST['client']??'');app_credential_origin($client,'webauthn.create');$r=$w->processCreate($client,app_binary($_POST['attestation']??''),$challenge,true,true);$id=hash('sha256',$r->credentialId);if(comm_get('passkey.'.$id))throw new RuntimeException('This passkey is already registered.');comm_put('passkey.'.$id,['id'=>$id,'user'=>(int)$u['id'],'credential'=>base64_encode($r->credentialId),'public'=>$r->credentialPublicKey,'counter'=>$r->signatureCounter??0,'label'=>reader_text($_POST['label']??'My passkey','Passkey name',80,true),'created'=>time()]);comm_json(['ok'=>true]);}
            if($action==='login_options'){$args=$w->getGetArgs([],120,true,true,true,true,true,true);$_SESSION['passkey_challenge']=['value'=>base64_encode($w->getChallenge()->getBinaryString()),'purpose'=>'login','expires'=>time()+180];comm_json(['ok'=>true,'options'=>$args]);}
            if($action==='login_finish'){$challenge=app_challenge('login');$credential=app_binary($_POST['credential']??'',4000);$id=hash('sha256',$credential);comm_lock('passkey.'.$id,function()use($w,$challenge,$id){$r=comm_get('passkey.'.$id);if(!$r)throw new InvalidArgumentException('Passkey sign-in could not be verified.');$q=db()->prepare('SELECT * FROM users WHERE id=? AND is_active=1');$q->execute([$r['user']]);$u=$q->fetch();if(!$u||login_rate_limited($u['email']))throw new InvalidArgumentException('Passkey sign-in could not be verified.');$client=app_binary($_POST['client']??'');app_credential_origin($client,'webauthn.get');$w->processGet($client,app_binary($_POST['authenticator']??''),app_binary($_POST['signature']??''),$r['public'],$challenge,$r['counter'],true,true);$handle=app_binary($_POST['handle']??'',1000);if(!hash_equals(hash_hmac('sha256','passkey-user|'.$u['id'],(string)app_config('app_key'),true),$handle))throw new InvalidArgumentException('Passkey user did not match.');$r['counter']=$w->getSignatureCounter()??$r['counter'];$r['last_used']=time();comm_put('passkey.'.$id,$r);session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));$_SESSION['auth_epoch']=(string)setting('auth.password_epoch.'.$u['id'],'');app_trust_issue((int)$u['id']);db()->prepare('UPDATE users SET last_login_at=NOW() WHERE id=?')->execute([$u['id']]);});comm_json(['ok'=>true,'url'=>'/write/communication']);}
            throw new InvalidArgumentException('Choose a supported passkey action.');
        }catch(Throwable $e){http_response_code(400);comm_json(['ok'=>false,'error'=>'Credential verification did not complete. Check your password or device prompt and start again.']);}
    }
    require_auth();$uid=(int)current_user()['id'];if(in_array($path,['/write/security/lock','/write/security/activity'],true)){journeys_method(['POST']);verify_csrf();if($path==='/write/security/lock'){$d=comm_get('session.'.app_device_id());$d['revoked']=true;comm_put('session.'.app_device_id(),$d);app_trust_forget();}else $_SESSION['interactive_at']=time();comm_json(['ok'=>true]);}if(is_post()){verify_csrf();try{$id=reader_text($_POST['id']??'','Device',64,true);if(!preg_match('/^[a-f0-9]{64}$/D',$id))throw new InvalidArgumentException('Choose a device.');
        if(($_POST['action']??'')==='revoke_session'){$d=comm_get('session.'.$id);if(($d['user']??0)!==$uid)throw new InvalidArgumentException('Choose your own session.');$d['revoked']=true;comm_put('session.'.$id,$d);app_trust_revoke($id,$uid);flash('success','Session access removed.');}
        elseif(($_POST['action']??'')==='remove_passkey'){app_password_check($uid,$_POST['password']??'');$r=comm_get('passkey.'.$id);if(($r['user']??0)!==$uid)throw new InvalidArgumentException('Choose your own passkey.');db()->prepare('DELETE FROM settings WHERE setting_key=?')->execute(['communication.passkey.'.$id]);flash('success','Passkey removed.');}
        redirect(url('/write/security'));
    }catch(Throwable $e){$error='The security change could not be completed. Check your password and selected device.';}}
    $sessions=array_filter(comm_records('session',1000),static fn($s)=>$s['user']===$uid);render_write('security',['writeTitle'=>'Devices & passkeys','error'=>$error,'sessions'=>$sessions,'passkeys'=>app_passkeys($uid)]);return true;
}
